import{_ as a,o as e,c as d,ag as s}from"./chunks/framework.i8sMDeRW.js";const g=JSON.parse('{"title":"大模型与 Harness 的未来轨迹","description":"","frontmatter":{},"headers":[],"relativePath":"guide/research/llm-harness-future-trajectory.md","filePath":"guide/research/llm-harness-future-trajectory.md","lastUpdated":1782288443000}'),r={name:"guide/research/llm-harness-future-trajectory.md"};function n(i,t,l,h,o,p){return e(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="大模型与-harness-的未来轨迹" tabindex="-1">大模型与 Harness 的未来轨迹 <a class="header-anchor" href="#大模型与-harness-的未来轨迹" aria-label="Permalink to &quot;大模型与 Harness 的未来轨迹&quot;">​</a></h1><blockquote><p><strong>2026-05 维护版</strong>：本文讨论 BigModel 与 BigHarness 的关系，提出三层 harness 分类框架，并给出面向 AI PM、Agent 平台设计者和 AI 基础设施创业者的产品判断。本文涉及较多快速变化的 benchmark、协议和厂商实践，结论应按季度复核。</p></blockquote><hr><h2 id="执行摘要" tabindex="-1">执行摘要 <a class="header-anchor" href="#执行摘要" aria-label="Permalink to &quot;执行摘要&quot;">​</a></h2><p>这场争论真正的答案，不是 <strong>BigModel</strong> 或 <strong>BigHarness</strong> 谁“吃掉一切”，而是：<strong>不同层的 harness 会被模型以不同速度吞并，最终留下来的价值主要集中在执行可信度、企业上下文与持续评估闭环</strong>。</p><p>模型正在吸收大量原本靠提示工程、任务分解和手写编排完成的能力：更长上下文、更强推理、更稳定工具调用、多模态理解、computer use、agent-native API 都在让“认知型 harness”变薄。但一旦问题进入真实组织环境，外部系统仍然不可替代：权限、审批、沙箱、预算、审计、回放、数据驻留、持续评估和事故响应不会因为模型更强而消失。</p><p>更准确地说，未来三到五年的趋势更可能是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>认知型 harness 变薄</span></span>
<span class="line"><span>交互型 harness 局部内生化</span></span>
<span class="line"><span>生产型 harness 外部化，并成为主要护城河</span></span></code></pre></div><p>因此，最优架构不是“更厚的编排”或“完全裸奔的模型”，而是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Model-native runtime</span></span>
<span class="line"><span>× Secure Context Fabric</span></span>
<span class="line"><span>× Verifiable Execution</span></span>
<span class="line"><span>× Continuous Evals</span></span></code></pre></div><hr><h2 id="_1-概念边界与三层-harness-分类" tabindex="-1">1. 概念边界与三层 Harness 分类 <a class="header-anchor" href="#_1-概念边界与三层-harness-分类" aria-label="Permalink to &quot;1. 概念边界与三层 Harness 分类&quot;">​</a></h2><p>本文将 <strong>harness</strong> 定义为：</p><blockquote><p>位于模型与环境之间，把上下文、工具、执行约束、反馈与治理组织成可运行系统的 agent 运行时。</p></blockquote><p>它不等于某个 prompt，也不等于某个框架。它包括 prompt、工具、memory、middleware、sandbox、policy、eval、trace、approval、billing、runtime 等多个层面。</p><table tabindex="0"><thead><tr><th>层级</th><th>核心问题</th><th>典型组件</th><th>主要失效模式</th><th>中期趋势判断</th></tr></thead><tbody><tr><td>认知型 harness</td><td>模型该想什么、先做什么、何时回看</td><td>系统提示、任务分解、路由、反思、RAG、记忆、查询改写</td><td>规划混乱、遗漏约束、上下文过载</td><td>最容易被更强模型和 test-time compute 吞并</td></tr><tr><td>交互型 harness</td><td>模型如何把意图可靠表达成动作</td><td>工具 schema、函数调用、编辑格式、GUI / 终端适配、参数约束</td><td>diff 失败、工具错配、GUI 脆弱、无限重试</td><td>会被部分内生化，但高质量 ACI 仍有价值</td></tr><tr><td>生产型 harness</td><td>系统如何在真实组织里安全、稳定、可审计地运行</td><td>身份、权限、审批、审计、trace、回放、沙箱、预算、SLA、eval</td><td>泄露、越权、成本失控、不可回放、线上退化</td><td>最不可能被模型内生化，最可能形成护城河</td></tr></tbody></table><hr><h2 id="_2-模型进步如何改变-harness" tabindex="-1">2. 模型进步如何改变 Harness <a class="header-anchor" href="#_2-模型进步如何改变-harness" aria-label="Permalink to &quot;2. 模型进步如何改变 Harness&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模型进步方向</th><th>对认知型 harness</th><th>对交互型 harness</th><th>对生产型 harness</th></tr></thead><tbody><tr><td>更强基座模型</td><td>压缩手写 prompt 链和分解套路</td><td>工具选择更稳</td><td>不替代权限、审计、预算</td></tr><tr><td>推理 RL / test-time compute</td><td>内生化 plan / reflect / replan</td><td>提升多步修复</td><td>增加对评估和控制面的要求</td></tr><tr><td>原生 tool use</td><td>让简单 router 变薄</td><td>仍依赖 schema 设计和参数约束</td><td>仍需外部策略执行</td></tr><tr><td>多模态 / computer use</td><td>吸收部分 UI 感知能力</td><td>降低无 API 场景的自动化门槛</td><td>更需要沙箱和审批</td></tr><tr><td>长上下文 / 记忆</td><td>减少摘要和压缩套路</td><td>更好消费外部状态</td><td>权限、鲜度、脱敏、provenance 更重要</td></tr><tr><td>模型原生 runtime</td><td>提升端到端体验</td><td>厂商 runtime 更强</td><td>企业仍需要 control plane</td></tr></tbody></table><p>关键判断：<strong>模型越强，越能吃掉“怎样想”；越接近“怎样安全地做”，外部系统越重要。</strong></p><hr><h2 id="_3-实证证据如何裁决争论" tabindex="-1">3. 实证证据如何裁决争论 <a class="header-anchor" href="#_3-实证证据如何裁决争论" aria-label="Permalink to &quot;3. 实证证据如何裁决争论&quot;">​</a></h2><p>最值得看的不是单个观点，而是不同 benchmark 和产品实践在什么条件下支持 BigModel，什么条件下支持 BigHarness。</p><table tabindex="0"><thead><tr><th>证据</th><th>设计重点</th><th>结论方向</th></tr></thead><tbody><tr><td>SWE-Atlas</td><td>真实代码库任务、原生 scaffold 与通用 harness 对比</td><td>支持 BigHarness：环境和交互形态会改变表现</td></tr><tr><td>Terminal-Bench</td><td>终端长程任务、模型与 agent 对比</td><td>支持 BigModel：模型跃迁是强变量，但 scaffold 仍重要</td></tr><tr><td>Agentic Harness Engineering</td><td>固定基座模型，自动进化 harness</td><td>支持 BigHarness：工具、middleware、memory 可带来显著增益</td></tr><tr><td>编辑工具格式研究</td><td>不换模型，仅改变编辑格式</td><td>支持交互型 harness：动作表达本身是性能边界</td></tr><tr><td>Cursor 工程实践</td><td>fast apply、Bugbot、long-running coding agent</td><td>支持产品化 harness：runtime + eval loop 可变成商业资产</td></tr><tr><td>AI Agent Index</td><td>观察已部署 agent 的透明度与安全评估</td><td>支持生产型 harness：安全、eval、透明度仍不足</td></tr></tbody></table><p>因此，更准确的裁决是：<strong>模型与 harness 不是一条轴上的替代关系，而是乘法关系</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务效果 ≈ 模型能力 × 上下文质量 × 动作接口 × 执行治理 × 评估反馈</span></span></code></pre></div><p>在“表征瓶颈”处，交互型 harness 常常带来比换一代模型还大的收益；在“可靠性瓶颈”处，生产型 harness 甚至是唯一可用的增益来源；只有在“纯认知瓶颈”处，模型升级才最像压倒性变量。</p><hr><h2 id="_4-标准化与护城河" tabindex="-1">4. 标准化与护城河 <a class="header-anchor" href="#_4-标准化与护城河" aria-label="Permalink to &quot;4. 标准化与护城河&quot;">​</a></h2><p>MCP、A2A、AGENTS.md、OpenAPI、JSON Schema、Structured Outputs 等标准会降低连接和工具接入成本。但标准化主要发生在线缆层，不会自动创造高质量上下文，也不会自动保证可信执行。</p><table tabindex="0"><thead><tr><th>资产类型</th><th>可被标准化程度</th><th>护城河判断</th></tr></thead><tbody><tr><td>通用 prompt 包装</td><td>高</td><td>弱</td></tr><tr><td>通用 agent UI</td><td>高</td><td>弱</td></tr><tr><td>通用连接器目录</td><td>很高</td><td>中偏弱</td></tr><tr><td>AGENTS.md 模板</td><td>高</td><td>中偏弱</td></tr><tr><td>私有上下文织网</td><td>低</td><td>强</td></tr><tr><td>权限、审批、审计系统</td><td>低</td><td>很强</td></tr><tr><td>线上 trace 和失败样例</td><td>很低</td><td>很强</td></tr><tr><td>私有 eval 数据集</td><td>很低</td><td>很强</td></tr><tr><td>深嵌业务工作流的分发位置</td><td>中</td><td>强</td></tr></tbody></table><p>关键判断：<strong>协议解决连接问题，不能替代治理问题。连接不是可信执行。</strong></p><hr><h2 id="_5-更优的混合架构" tabindex="-1">5. 更优的混合架构 <a class="header-anchor" href="#_5-更优的混合架构" aria-label="Permalink to &quot;5. 更优的混合架构&quot;">​</a></h2><p>默认推荐架构：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> U[用户或业务事件] --&gt; P[策略与权限网关]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> P --&gt; C[安全上下文织网]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> C --&gt; M[模型原生推理与工具调用]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> M &lt;--&gt; T[类型化工具层]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> T --&gt; S[隔离执行沙箱]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> S --&gt; V[验证器与回归测试]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> V --&gt; M</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> V --&gt; A[审计与反馈仓]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> A --&gt; C</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> P --&gt; H[人工审批与升降级]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> H --&gt; S</span></span></code></pre></div><p>核心原则：</p><ol><li>让模型承担理解、规划、选择、局部修复；</li><li>让外部系统承担权限、上下文治理、执行隔离、审计和评估；</li><li>把 compute plane 和 control plane 分开；</li><li>把工具 schema、权限和审批视为产品设计，而不是工程细节；</li><li>用线上 trace 和失败样例建立持续评估飞轮。</li></ol><h3 id="五种可落地方案" tabindex="-1">五种可落地方案 <a class="header-anchor" href="#五种可落地方案" aria-label="Permalink to &quot;五种可落地方案&quot;">​</a></h3><table tabindex="0"><thead><tr><th>架构方案</th><th>适用场景</th><th>必要组件</th></tr></thead><tbody><tr><td>模型原生运行时</td><td>研发、知识工作、轻量自动化</td><td>agent-native API、内置工具、基础沙箱</td></tr><tr><td>安全上下文织网</td><td>企业知识、跨系统工作流</td><td>RAG、知识图谱、ACL、provenance、freshness</td></tr><tr><td>可验证执行闭环</td><td>金融、法务、医疗、代码发布</td><td>plan-execute-verify、测试、trace、审批</td></tr><tr><td>神经—符号双控制器</td><td>强规则、强合规场景</td><td>LLM planner、policy engine、typed tools</td></tr><tr><td>边缘个性化 + 云验证</td><td>隐私敏感、强个性化助手</td><td>端侧记忆、小模型、云侧验证和审计</td></tr></tbody></table><hr><h2 id="_6-建议优先做的实验" tabindex="-1">6. 建议优先做的实验 <a class="header-anchor" href="#_6-建议优先做的实验" aria-label="Permalink to &quot;6. 建议优先做的实验&quot;">​</a></h2><table tabindex="0"><thead><tr><th>实验</th><th>要验证的命题</th><th>建议指标</th></tr></thead><tbody><tr><td>同模型多编辑格式 A/B</td><td>交互型 harness 是否比换模型更值钱</td><td>成功率、重试次数、人工修复率</td></tr><tr><td>原生 scaffold vs 通用 scaffold</td><td>原生运行时是否改变探索质量</td><td>exploration 次数、执行率、pass@1</td></tr><tr><td>上下文质量分层实验</td><td>企业上下文资产是不是护城河</td><td>正确率、越权率、澄清次数</td></tr><tr><td>策略外置 vs 模型内约束</td><td>生产型 harness 是否降低事故率</td><td>越权率、泄露率、误报率</td></tr><tr><td>单 Agent vs 多 Agent</td><td>多 Agent 何时值得</td><td>成功率、延迟、成本、错误放大倍数</td></tr></tbody></table><hr><h2 id="_7-对创业公司和企业的建议" tabindex="-1">7. 对创业公司和企业的建议 <a class="header-anchor" href="#_7-对创业公司和企业的建议" aria-label="Permalink to &quot;7. 对创业公司和企业的建议&quot;">​</a></h2><ul><li><strong>先按三层拆问题，再决定投入点。</strong> 如果失败在动作表达，优先改交互层；如果失败在越权、回归、不可审计，优先改生产层。</li><li><strong>把 compute plane 与 control plane 分开。</strong> 模型可以换，权限、预算、审批、审计不能跟着模型漂移。</li><li><strong>尽快建立类型化工具契约。</strong> 至少做到 JSON Schema、参数约束、最小权限和白名单动作。</li><li><strong>把私有上下文做成产品层，而不是 prompt 层。</strong> 清洗、权限、鲜度、provenance 和语义索引都应进入可治理资产库。</li><li><strong>持续评测要前置。</strong> 用任务级 eval、轨迹级 eval 和线上 trace 形成闭环。</li><li><strong>标准化要拥抱，但不要把标准当护城河。</strong> MCP、A2A、AGENTS.md 会降低互联成本，真正差异在 context、trust、distribution。</li><li><strong>多代理不是默认答案。</strong> 只有当任务可并行、边界清楚、工具密度可控时才值得。</li><li><strong>高风险场景从可验证动作切入。</strong> 先可证明、可回放、可签名，再逐步扩大自治范围。</li></ul><hr><h2 id="_8-本文边界" tabindex="-1">8. 本文边界 <a class="header-anchor" href="#_8-本文边界" aria-label="Permalink to &quot;8. 本文边界&quot;">​</a></h2><ol><li>公开 benchmark 仍偏 coding / knowledge work，对线下运营、客服、供应链、财务等任务的外推有限；</li><li>很多厂商只公开结果，不公开 runtime 细节和失败轨迹；</li><li>资本市场估值和媒体报道只能作为商业态度旁证，不能直接当作技术结论；</li><li>本文引用的模型、产品、benchmark 更新很快，应按季度复核。</li></ol><hr><h2 id="_9-参考来源" tabindex="-1">9. 参考来源 <a class="header-anchor" href="#_9-参考来源" aria-label="Permalink to &quot;9. 参考来源&quot;">​</a></h2><p>以下来源可用于支撑本文的主要判断，并建议后续维护时优先复核：</p><table tabindex="0"><thead><tr><th>来源</th><th>用途</th></tr></thead><tbody><tr><td>OpenAI — Harness engineering: leveraging Codex in an agent-first world</td><td>agent-first 工程、harness 与控制系统</td></tr><tr><td>OpenAI Agents SDK / Responses API 文档</td><td>model-native runtime、工具调用、沙箱和 agent primitives</td></tr><tr><td>Anthropic — Building effective agents</td><td>workflows、agents、ACI、工具设计</td></tr><tr><td>Anthropic — Model Context Protocol</td><td>MCP 标准和工具连接生态</td></tr><tr><td>Google Agent2Agent / A2A Protocol</td><td>Agent 间通信和协作标准</td></tr><tr><td>AGENTS.md 项目</td><td>项目级 agent 指令约定</td></tr><tr><td>Agentic Harness Engineering paper</td><td>固定模型下 harness 改进的实证证据</td></tr><tr><td>Scale AI — SWE-Atlas</td><td>真实代码库任务和 scaffold 对表现的影响</td></tr><tr><td>Terminal-Bench / Terminal-Bench 2.0</td><td>终端长程任务和模型/agent 能力比较</td></tr><tr><td>METR — Measuring AI Ability to Complete Long Tasks</td><td>AI 可完成任务时长的能力外推</td></tr><tr><td>Stanford AI Index</td><td>产业级 AI 能力、benchmark、采用趋势</td></tr><tr><td>MIT AI Agent Index</td><td>已部署 agent 的透明度、安全和评估实践</td></tr><tr><td>Cursor Engineering Blog</td><td>fast apply、Bugbot、long-running coding agent 的产品化 harness 实践</td></tr><tr><td>OWASP Top 10 for LLM Applications</td><td>Prompt 注入、工具安全、供应链和数据泄露风险</td></tr><tr><td>NIST AI Risk Management Framework</td><td>AI 风险管理和治理框架</td></tr></tbody></table><hr><h2 id="_10-维护建议" tabindex="-1">10. 维护建议 <a class="header-anchor" href="#_10-维护建议" aria-label="Permalink to &quot;10. 维护建议&quot;">​</a></h2><ul><li>每季度复核 benchmark 名称、分数和模型名；</li><li>具体数字尽量移动到脚注或参考来源，避免正文长期失效；</li><li>对未公开细节的厂商案例使用“推断”“媒体报道”“公开工程博客显示”等限定语；</li><li>若未来模型原生 runtime 明显成熟，应重新评估交互型 harness 的剩余价值；</li><li>若监管加强，应提高生产型 harness 中审计、审批和合规的权重。</li></ul><hr><p><em>本文是 AI PM Playbook「📡 研究方向」系列的一部分。更多研究文章请访问 <a href="https://github.com/prodthinkpm/ai-pm-playbook" target="_blank" rel="noreferrer">AI PM Playbook</a>。</em></p>`,58)])])}const u=a(r,[["render",n]]);export{g as __pageData,u as default};
